package app.kinnect.live;
import android.app.Activity;import android.graphics.Color;import android.util.TypedValue;import android.view.*;import android.widget.*;import org.json.JSONObject;
/** One compact balance layout shared by Wallet and Shop. */
final class CoinBalanceCard extends LinearLayout {
 static android.graphics.drawable.Drawable coin(Activity a,int size){int id=a.getResources().getIdentifier("ic_web_coins","drawable",a.getPackageName());android.graphics.drawable.Drawable d=a.getDrawable(id).mutate();d.setBounds(0,0,size,size);return d;}
 static String display(long value){java.text.NumberFormat f=java.text.NumberFormat.getInstance(new java.util.Locale("vi","VN"));if(value>999999999L){f.setMaximumFractionDigits(2);return f.format(value/1000000000.0)+(I18n.current().equals("en")?" B":" tỷ");}return f.format(value);}
 CoinBalanceCard(Activity a,JSONObject data,boolean compact,boolean hidden,Runnable toggle){super(a);CommerceUi ui=new CommerceUi(a);setOrientation(VERTICAL);setPadding(ui.dp(16),ui.dp(compact?12:14),ui.dp(16),ui.dp(compact?12:14));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{0xff5d36d6,0xff9655ec,0xffd35ab6});bg.setCornerRadius(ui.dp(18));setBackground(bg);setTag(compact?"store:balance":"wallet:balance");LinearLayout top=ui.row();TextView title=ui.text("Số dư",12,0xfff2edff,true);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));if(toggle!=null){FrameLayout eye=ui.icon(hidden?"eye_off":"eye","Ẩn / hiện số dư",toggle);eye.setBackgroundColor(Color.TRANSPARENT);((ImageView)eye.getChildAt(0)).setColorFilter(Color.WHITE);top.addView(eye,new LinearLayout.LayoutParams(ui.dp(40),ui.dp(40)));}addView(top);{LinearLayout row=ui.row();row.setGravity(Gravity.TOP);for(int i=0;i<2;i++){boolean paid=i==0;LinearLayout cell=ui.col();cell.setPadding(paid?0:ui.dp(12),ui.dp(compact?8:10),paid?ui.dp(12):0,0);TextView label=ui.text(paid?"Xu mua":"Xu tặng",11,0xfff2edff,false);android.graphics.drawable.Drawable symbol=paid?coin(a,ui.dp(18)):ui.glyph("gift",Color.WHITE,16);label.setCompoundDrawablesRelative(symbol,null,null,null);label.setCompoundDrawablePadding(ui.dp(6));label.setMinHeight(ui.dp(28));cell.addView(label);long value=paid?data.optLong("purchasedCoins"):data.optLong("giftedCoins",data.optLong("trialCoins"));TextView amount=ui.text(hidden?"••••":display(value),compact?20:24,Color.WHITE,true);amount.setSingleLine(true);amount.setHorizontallyScrolling(false);amount.setAutoSizeTextTypeUniformWithConfiguration(12,compact?20:24,1,TypedValue.COMPLEX_UNIT_SP);amount.setMinHeight(ui.dp(40));amount.setTag(compact?"store:balance:"+(paid?"purchasedCoins":"trialCoins"):paid?"wallet:purchased":"wallet:coins");amount.setContentDescription(I18n.t(paid?"Xu mua":"Xu tặng")+" · "+value);cell.addView(amount,new LinearLayout.LayoutParams(-1,-2));row.addView(cell,new LinearLayout.LayoutParams(0,-2,1));if(i==0){View divider=new View(a);divider.setBackgroundColor(0x55ffffff);LinearLayout.LayoutParams at=new LinearLayout.LayoutParams(ui.dp(1),ui.dp(40));at.topMargin=ui.dp(8);row.addView(divider,at);}}addView(row);}}
}
